extends RefCounted
## Deterministic placeholder world for tests and balance simulations.
## NOT part of the kernel contract: a real host replaces this with combat,
## crowd and rendering systems. It exists so the kernel can be driven through
## full operations without UI/3D, and so GREEDY consequences become measurable.
##
## Combat model (crude by design):
## - each unresolved batch leaks role.leak_dps * count * aggression to Core per second;
## - turrets (registered assets) shoot their assigned lane while ammo lasts;
## - pilot policy splits attention across threatened lanes;
## - batches die when their pooled HP reaches zero -> BATCH_RESOLVED reported.

const Kernel := preload("res://mission/mission_kernel.gd")

const PILOT_DPS := 45.0
const TURRET_DPS := 20.0
const RESUPPLY_DELAY_STEPS := 30

var k: Object                      # mission kernel instance
var step_sec: float = 0.1
var policy: String = "balanced"    # balanced | core_camp | passive | turretless
var ammo: int = 0
var resupply_pending_at: int = -1
var core_damage_debt: float = 0.0
var live: Dictionary = {}          # batch_id -> {lane, role, count, hp, leak_per_step}
var _events_cursor: int = 0
var rng := RandomNumberGenerator.new()


static func create(mission_cfg: Dictionary, pilot_policy: String = "balanced") -> Object:
	var h := new()
	h.k = Kernel.new()
	h.policy = pilot_policy
	h.step_sec = float(mission_cfg.timing.fixed_step_ms) / 1000.0
	h.ammo = int(mission_cfg.get("supply", {}).get("initial_ammo", 120))
	assert(h.k.configure(mission_cfg).accepted)
	h.k.event_emitted.connect(h._on_event)
	return h


func start() -> void:
	for socket in ["TURRET_A", "TURRET_B"]:
		k.cmd("ASSET_REGISTERED", {"asset_id": socket, "type": "TURRET_MG"})
	k.cmd("START_WAVE")


## One world step: advance kernel clock, then simulate host consequences.
func advance(seconds: float) -> void:
	k.advance(seconds)
	_tick_world()


func advance_until(predicate: Callable, max_steps: int = 60000) -> bool:
	var guard := 0
	while not predicate.call() and guard < max_steps:
		guard += 1
		k.advance(step_sec)
		_tick_world()
	return predicate.call()


# ------------------------------------------------------------------ world sim

func _on_event(e: Dictionary) -> void:
	match e.kind:
		"SPAWN_INTENT":
			var roles: Dictionary = k.cfg.get("roles", {})
			var role: Dictionary = roles.get(e.role, {"hp_per_unit": 30, "leak_dps": 4})
			live[e.batch_id] = {
				"lane": e.lane,
				"role": e.role,
				"count": e.count,
				"hp": float(role.hp_per_unit) * float(e.count),
				"leak_per_step": float(role.leak_dps) * float(e.count) * float(e.aggression) * step_sec,
			}
		"RESUPPLY_WINDOW_OPENED":
			resupply_pending_at = k.step + RESUPPLY_DELAY_STEPS


func _tick_world() -> void:
	if resupply_pending_at > 0 and k.step >= resupply_pending_at:
		var amount := int(k.cfg.get("supply", {}).get("resupply_per_intermission", 60))
		k.cmd("RESUPPLY_DELIVERED", {"amount": amount})
		ammo += amount
		resupply_pending_at = -1

	if live.is_empty():
		return

	var lane_ids := {}
	for id in live:
		lane_ids[live[id].lane] = true

	var turret_lanes := {"TURRET_A": "A", "TURRET_B": "B"}
	var pilot_lane_coverage: Array = []
	match policy:
		"balanced":
			pilot_lane_coverage = lane_ids.keys()
		"core_camp":
			pilot_lane_coverage = lane_ids.keys().filter(func(l): return l != "C")
		_:
			pass  # passive / turretless: no personal intervention

	var per_lane_pilot := PILOT_DPS * step_sec / maxf(1.0, float(pilot_lane_coverage.size()))

	var damage_by_batch: Dictionary = {}
	for id in live:
		var b: Dictionary = live[id]
		var dmg := 0.0
		if ammo > 0 and policy != "turretless":
			for socket in turret_lanes:
				if turret_lanes[socket] == b.lane and ammo > 0:
					dmg += TURRET_DPS * step_sec
					ammo -= 1
					k.cmd("AMMO_SPENT", {"amount": 1})
		if b.lane in pilot_lane_coverage and policy != "passive" and policy != "turretless":
			dmg += per_lane_pilot
		damage_by_batch[id] = dmg

	# focus fire: strongest batch in its lane takes the lane's total damage
	for lane in lane_ids:
		var lane_batches := live.keys().filter(func(id): return live[id].lane == lane)
		if lane_batches.is_empty():
			continue
		lane_batches.sort_custom(func(a, b): return live[a].hp > live[b].hp)
		var pool := 0.0
		for id in lane_batches:
			pool += damage_by_batch[id]
		live[lane_batches[0]].hp -= pool

	var core_leak := 0.0
	var dead: Array = []
	for id in live:
		var b: Dictionary = live[id]
		core_leak += b.leak_per_step
		if b.hp <= 0.0:
			dead.append(id)
	for id in dead:
		live.erase(id)
		k.cmd("BATCH_RESOLVED", {"batch_id": id})

	if core_leak > 0.0 and k.core_hp > 0:
		core_damage_debt += core_leak
		var whole := int(floor(core_damage_debt + 0.000001))
		if whole > 0:
			core_damage_debt -= float(whole)
			k.cmd("CORE_DAMAGE", {"amount": whole, "source": "SIM_LEAK"})

extends RefCounted
## VS3-T1 regression: fractional advance() calls accumulate across frames so a
## 60 fps host loop feeding advance(0.016) still crosses 100 ms step boundaries.
## The old int(round(...)) implementation silently produced 0 steps per frame.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")
const Defs := preload("res://mission/defs.gd")
const KernelScript := preload("res://mission/mission_kernel.gd")


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "advance_fractional"

	var k := KernelScript.new()
	var cfg: Dictionary = t.load_cfg("mission_default.json")
	t.ok(k.configure(cfg).accepted, "configure accepted")
	t.eq(int(k.state()["step"]), 0, "step starts at 0")

	for i in 60:
		k.advance(0.016)
	# 60 x 16 ms = 960 ms -> 9 full 100 ms steps, 60 ms carried as debt.
	# Old int(round(...)) implementation produced 0 here (clock stall).
	t.eq(int(k.state()["step"]), 9, "60 x advance(0.016) == 9 steps (old code: 0)")

	for i in 50:
		k.advance(0.016)
	t.eq(int(k.state()["step"]), 17, "+50 frames (800 ms + 60 ms debt) == 8 more steps")

	var before := int(k.state()["step"])
	k.advance(1.0)
	t.eq(int(k.state()["step"]) - before, 10, "advance(1.0) still yields exactly 10 steps")

	return t.result()

extends RefCounted
## Test case: continue-for-more - decline extraction at quota, keep harvesting,
## de-escalate risk for the last wave, extract with a bigger payout.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")


func _conclude(h) -> void:
	var guard := 0
	while h.k.phase != "CONCLUDED" and guard < 40000:
		guard += 1
		if h.k.phase == "SCOUT":
			h.k.cmd("START_WAVE")
		elif h.k.phase == "INTERMISSION":
			if h.k.final_lull:
				h.k.cmd("REQUEST_WITHDRAWAL")
			else:
				h.k.cmd("START_WAVE")
		h.advance(h.step_sec)


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "continue_for_more"
	var cfg: Dictionary = t.load_cfg("mission_default.json")

	# baseline: greedy early exit the moment quota is met
	var h_early = t.Harness.create(cfg, "balanced")
	h_early.k.cmd("SET_RISK", {"mode": "GREEDY"})
	t.auto_run(h_early, func(_p, _w): return "", func(_h): return true)

	# greedy start, but continue past quota; drop to SAFE before wave 3
	var h_full = t.Harness.create(cfg, "balanced")
	h_full.k.cmd("SET_RISK", {"mode": "GREEDY"})
	t.auto_run(h_full,
		func(phase, waves_completed):
			if phase == "INTERMISSION" and int(waves_completed) == 2:
				return "SAFE"  # risk management for the final push
			return "",
		func(_h): return false)  # never withdraw early

	_conclude(h_early)
	_conclude(h_full)

	t.eq(h_early.k.outcome.get("outcome", ""), "SUCCESS", "early variant concluded successfully")
	t.eq(h_full.k.outcome.get("outcome", ""), "SUCCESS", "continue-for-more variant concluded successfully")

	var ex_early: int = h_early.k.ex_mex
	var ex_full: int = h_full.k.ex_mex
	t.ok(ex_full > ex_early,
		"continuing yields more EX than early exit (%d vs %d)" % [ex_full, ex_early])
	t.ok(ex_full - ex_early > int(0.3 * ex_early),
		"extra EX is material (>30% of early payout), making the choice real")
	t.eq(h_full.k.state().kpis.extraction_timing, "FULL", "continued run timing FULL")
	return t.result()

extends RefCounted
## Test case: Core destroyed -> FAILURE; critical threshold fires once;
## a passive defense run dies emergently.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "core_destroyed_failure"

	# --- direct kernel-level truth
	var h = t.Harness.create(t.load_cfg("mission_default.json"), "balanced")
	h.k.cmd("START_WAVE")
	h.k.cmd("CORE_DAMAGE", {"amount": 1600, "source": "TEST"})
	t.ok(h.k.phase == "ASSAULT", "core damaged but operation continues")
	t.eq(h.k.telemetry.count_kind("CORE_CRITICAL"), 1, "CORE_CRITICAL fired at <=25% hp")
	h.k.cmd("CORE_DAMAGE", {"amount": 600, "source": "TEST"})
	t.eq(h.k.outcome.get("outcome", ""), "FAILURE", "core destruction fails operation")
	t.eq(h.k.outcome.get("reason", ""), "CORE_DESTROYED", "failure reason recorded")
	t.eq(h.k.state().kpis.core_survived, false, "KPI core_survived false")
	t.eq(h.k.telemetry.count_kind("CORE_CRITICAL"), 1, "critical threshold fires once only")
	var over_damage: Dictionary = h.k.cmd("CORE_DAMAGE", {"amount": 10, "source": "TEST"})
	t.ok(not over_damage.accepted, "damage after death rejected")

	# --- emergent destruction via placeholder combat model (passive pilot)
	var h2 = t.Harness.create(t.load_cfg("mission_default.json"), "passive")
	h2.k.cmd("START_WAVE")
	var guard := 0
	while h2.k.phase != "CONCLUDED" and guard < 20000:
		guard += 1
		h2.advance(h2.step_sec)
		if h2.k.phase == "INTERMISSION":
			h2.k.cmd("START_WAVE")
	t.eq(h2.k.outcome.get("outcome", ""), "FAILURE", "passive defense loses eventually")
	t.eq(h2.k.outcome.get("reason", ""), "CORE_DESTROYED", "emergent loss is core destruction")
	return t.result()

extends RefCounted
## Test case: deterministic replay - same seed + same command stream => identical
## telemetry digest, state and KPIs. Different seed => different run.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")


func _scripted_run(cfg: Dictionary) -> Object:
	var h = Util.Harness.create(cfg, "balanced")
	h.k.cmd("SET_RISK", {"mode": "GREEDY"})
	var guard := 0
	while h.k.phase != "CONCLUDED" and guard < 40000:
		guard += 1
		match h.k.phase:
			"SCOUT":
				h.k.cmd("START_WAVE")
			"ASSAULT":
				if int(h.k.step) == 500:
					h.k.cmd("SET_RISK", {"mode": "SAFE"})  # mid-wave de-escalation
			"INTERMISSION":
				if h.k.quota_met:
					h.k.cmd("REQUEST_WITHDRAWAL")
				else:
					h.k.cmd("START_WAVE")
		h.advance(h.step_sec)
	return h


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "deterministic_replay"
	var cfg: Dictionary = t.load_cfg("mission_default.json")

	var a = _scripted_run(cfg)
	var b = _scripted_run(cfg)

	t.eq(a.k.telemetry.digest(), b.k.telemetry.digest(),
		"identical command stream -> identical telemetry digest")
	t.eq(a.k.step, b.k.step, "same final step")
	t.eq(a.k.ex_mex, b.k.ex_mex, "same final EX")
	t.eq(a.k.core_hp, b.k.core_hp, "same final core hp")
	t.eq(JSON.stringify(a.k.kpis()), JSON.stringify(b.k.kpis()), "identical KPIs")

	var cfg2: Dictionary = cfg.duplicate(true)
	cfg2.meta.seed = 99
	var c = _scripted_run(cfg2)
	t.ok(a.k.telemetry.digest() != c.k.telemetry.digest(), "different seed changes the run")

	var hc: Dictionary = t.load_cfg("mission_harassment.json")
	var d1 = _scripted_run(hc)
	var d2 = _scripted_run(hc)
	t.eq(d1.k.telemetry.digest(), d2.k.telemetry.digest(), "harassment config replays identically")
	return t.result()

extends RefCounted
## Test case: early extraction - quota met mid-operation, withdraw immediately.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "early_extraction"
	var h = t.Harness.create(t.load_cfg("mission_default.json"), "balanced")
	h.k.cmd("SET_RISK", {"mode": "GREEDY"})
	h.k.cmd("START_WAVE")

	var guard := 0
	while not h.k.quota_met and h.k.phase != "CONCLUDED" and guard < 40000:
		guard += 1
		if h.k.phase == "INTERMISSION":
			h.k.cmd("START_WAVE")
		h.advance(h.step_sec)
	t.ok(h.k.quota_met, "quota reached during operation")
	var ready_at: int = h.k.step
	t.ok(h.k.waves_completed < 3, "quota crossed before all waves done (waves_done=%d)" % h.k.waves_completed)

	var res: Dictionary = h.k.cmd("REQUEST_WITHDRAWAL")
	t.ok(res.accepted, "withdrawal accepted once quota met mid-wave")
	t.eq(h.k.phase, "WITHDRAWAL", "entered WITHDRAWAL")

	guard = 0
	while h.k.phase != "CONCLUDED" and guard < 5000:
		guard += 1
		h.advance(h.step_sec)

	t.eq(h.k.outcome.get("outcome", ""), "SUCCESS", "early extraction concludes the contract")
	if h.k.outcome.get("outcome", "") == "SUCCESS":
		t.eq(h.k.state().kpis.extraction_timing, "EARLY", "timing marked EARLY")
		t.ok(h.k.waves_completed < 3, "contract closed before final wave resolved")
	t.ok(h.k.step > ready_at, "extraction channel consumed time")
	return t.result()

extends RefCounted
## Test case: GREEDY full run - pressure contract changes character, not just numbers.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "greedy_full_run"
	var h = t.Harness.create(t.load_cfg("mission_default.json"), "balanced")
	h.k.cmd("SET_RISK", {"mode": "GREEDY"})
	t.auto_run(h, func(_p, _w): return "", func(_h): return h.k.final_lull)

	t.eq(h.k.outcome.get("outcome", ""), "SUCCESS", "greedy operation succeeds")
	t.eq(h.k.waves_completed, 3, "all three waves completed under GREEDY")
	t.ok(h.k.risk_id == "GREEDY", "risk mode is GREEDY at end")

	# GREEDY consequences visible in kernel facts:
	var w1_intents: Array = t.intents_of_wave(h, 1)
	t.ok(w1_intents.size() > 0, "wave 1 produced intents")
	var w1_lanes := {}
	for e in w1_intents:
		w1_lanes[e.lane] = true
	t.ok(w1_lanes.size() == 1 and w1_lanes.has("A"),
		"Doctrine remains one authored lane even under GREEDY; C is reserved for Breakdown")
	var any_aggr_scaled := false
	for e in w1_intents:
		if absf(float(e.aggression) - 1.15) < 0.001:
			any_aggr_scaled = true
	t.ok(any_aggr_scaled, "AGGRESSION budget scaled in emitted intents (x1.15)")

	# intel quality degraded on the next-wave preview
	var preview: Dictionary = h.k.telemetry.last_of_kind("THREAT_PREVIEW")
	if not preview.is_empty():
		t.ok(float(preview.intel_quality) < 1.0, "threat preview fidelity reduced under GREEDY")

	# cadence compressed: first batch of W1 arrives earlier than SAFE baseline
	t.ok(int(w1_intents[0].step) <= 60, "SPAWN_CADENCE compression pulls first contact earlier")

	return t.result()

extends RefCounted
## Test case: contract edge - final wave clears while quota unmet -> automatic
## FAILURE(QUOTA_UNMET). Also: telemetry is machine-readable and dumpable.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "quota_unmet_and_telemetry"
	var cfg: Dictionary = t.load_cfg("mission_default.json")
	cfg = cfg.duplicate(true)
	cfg.extraction.quota_mex = 99999999999  # unreachable
	cfg.waves = [cfg.waves[0]]              # single short wave

	var h = t.Harness.create(cfg, "balanced")

	# --- host metric channel (day-one telemetry contract)
	var mr: Dictionary = h.k.cmd("REPORT_METRIC", {"key": "turret_damage_mg", "value": 4210})
	t.ok(mr.accepted, "metric report accepted")
	t.ok(not h.k.cmd("REPORT_METRIC", {"key": ""}).accepted, "empty metric key rejected")

	h.k.cmd("START_WAVE")
	var guard := 0
	while h.k.phase != "CONCLUDED" and guard < 30000:
		guard += 1
		h.advance(h.step_sec)
		if h.k.phase == "INTERMISSION" and not h.k.final_lull:
			h.k.cmd("START_WAVE")

	t.eq(h.k.outcome.get("outcome", ""), "FAILURE", "unreachable quota fails the contract")
	t.eq(h.k.outcome.get("reason", ""), "QUOTA_UNMET", "failure reason QUOTA_UNMET")

	# --- telemetry contract
	var log_path := "res://results/test_telemetry_sample.jsonl"
	t.ok(h.k.telemetry.dump_jsonl(log_path), "telemetry dumps to JSONL")
	var f := FileAccess.open(log_path, FileAccess.READ)
	t.ok(f != null, "dump readable")
	if f != null:
		var first: Variant = JSON.parse_string(f.get_line())
		t.ok(typeof(first) == TYPE_DICTIONARY and first.has("kind") and first.has("step"),
			"JSONL lines are machine-readable objects")
		f.close()

	for kind in ["MISSION_CONFIGURED", "PHASE_CHANGED", "EX_TICK", "METRIC_REPORTED",
			"CORE_DAMAGED", "WAVE_STARTED", "WAVE_COMPLETED", "OPERATION_RESOLVED"]:
		t.ok(h.k.telemetry.count_kind(kind) > 0, "telemetry covers %s" % kind)
	return t.result()

extends RefCounted
## Test case: switch GREEDY -> SAFE - pressure contract de-escalates.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "switch_greedy_to_safe"
	var h = t.Harness.create(t.load_cfg("mission_default.json"), "balanced")
	h.k.cmd("SET_RISK", {"mode": "GREEDY"})
	h.k.cmd("START_WAVE")
	h.k.advance(h.step_sec * 100)
	h._tick_world()

	var res: Dictionary = h.k.cmd("SET_RISK", {"mode": "SAFE"})
	t.ok(res.accepted, "mid-wave GREEDY->SAFE accepted")

	# aggression of newly emitted intents drops back to wave baseline
	h.advance_until(func(): return h.k.phase == "INTERMISSION" or h.k.phase == "CONCLUDED")
	var late_intents: Array = h.k.telemetry.events.filter(func(e):
		return e.kind == "SPAWN_INTENT" and int(e.step) > 100)
	var saw_baseline := false
	for e in late_intents:
		if absf(float(e.aggression) - float(h.k.cfg.waves[0].aggression)) < 0.001:
			saw_baseline = true
	t.ok(saw_baseline, "post-switch intents carry baseline aggression (de-escalated)")

	if h.k.phase == "ASSAULT":
		t.ok(float(h.k.get_plan().intel_quality) >= 1.0, "active plan intel restored to SAFE quality")
	return t.result()

extends RefCounted
## Test case: switch SAFE -> GREEDY (mid-wave and intermission), both effective.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "switch_safe_to_greedy"
	var h = t.Harness.create(t.load_cfg("mission_default.json"), "balanced")
	h.k.cmd("START_WAVE")

	# --- mid-wave switch during ASSAULT (wave 1)
	var ex_before: int = h.k.ex_mex
	h.k.advance(h.step_sec * 120)  # ~12s into wave 1
	h._tick_world()
	var res: Dictionary = h.k.cmd("SET_RISK", {"mode": "GREEDY"})
	t.ok(res.accepted, "mid-wave SAFE->GREEDY accepted")
	var replan: Dictionary = h.k.telemetry.last_of_kind("WAVE_REPLANNED")
	t.ok(not replan.is_empty(), "WAVE_REPLANNED emitted on mid-wave switch")

	# replanned schedule contains only future batches at the moment of the switch
	var now_at_switch: int = h.k.step
	var stale := false
	for b in h.k.get_plan().batches:
		if int(b.at_step) <= now_at_switch:
			stale = true
	t.ok(not stale, "replanned schedule contains only future batches")

	# extraction rate jumped immediately
	h.k.advance(h.step_sec * 50)
	h._tick_world()
	var ex_gained: int = h.k.ex_mex - ex_before
	t.ok(ex_gained > 0, "EX accrued after switch")

	# --- intermission switch before wave 2
	h.advance_until(func(): return h.k.phase == "INTERMISSION" or h.k.phase == "CONCLUDED")
	if h.k.phase == "INTERMISSION":
		var r2: Dictionary = h.k.cmd("SET_RISK", {"mode": "SAFE"})
		t.ok(r2.accepted, "GREEDY->SAFE at intermission accepted")
		h.k.cmd("START_WAVE")
		var plan_ev: Dictionary = h.k.telemetry.last_of_kind("WAVE_PLANNED")
		t.ok(absf(float(plan_ev.aggression) - 1.1) < 0.001,
			"wave 2 planned with SAFE aggression (no GREEDY multiplier)")
		t.ok(absf(float(plan_ev.intel_quality) - 1.0) < 0.001, "intel quality restored under SAFE")

	var risks: Array = []
	for e in h.k.telemetry.events:
		if e.kind == "RISK_CHANGED":
			risks.append("%s->%s:%s" % [e.from, e.to, e.effective])
	t.ok(risks.size() >= 2, "risk timeline recorded (%s)" % str(risks))
	return t.result()
